import random


def is_quadratic_residue(a, p):
    """a 是否为模 p 二次剩余（a=0 视为剩余）"""
    return a == 0 or pow(a, (p - 1) // 2, p) == 1


def cipolla(a, p):
    """求 x 使 x^2≡a (mod p)，p 为奇素数。返回一个根或 -1（无解）。
    另一个根为 p - x。
    """
    if a == 0:
        return 0
    if not is_quadratic_residue(a, p):
        return -1

    # 找一个 b 使 w2 = b^2 - a 为二次非剩余
    while True:
        b = random.randrange(0, p)
        w2 = (b * b - a) % p
        if w2 != 0 and pow(w2, (p - 1) // 2, p) == p - 1:
            break

    # 扩域元素 (u, v) 表示 u + v*t，其中 t^2 = w2
    def mul(x, y):
        u1, v1 = x
        u2, v2 = y
        return ((u1 * u2 + v1 * v2 * w2) % p,
                (u1 * v2 + v1 * u2) % p)

    base = (b % p, 1)  # b + t
    res = (1, 0)
    e = (p + 1) // 2
    while e:
        if e & 1:
            res = mul(res, base)
        base = mul(base, base)
        e >>= 1
    x = res[0] % p  # 虚部应为 0
    assert (x * x - a) % p == 0
    return x


if __name__ == "__main__":
    for p in [7, 11, 13, 17, 19, 23, 29, 31, 101, 1009, 9973]:
        for a in range(p):
            if a == 0:
                assert cipolla(0, p) == 0
                continue
            if is_quadratic_residue(a, p):
                x = cipolla(a, p)
                assert x * x % p == a, (p, a, x)
            else:
                assert cipolla(a, p) == -1, (p, a)
        # 特殊 p：p≡3 mod 4 直接用公式验证
    for p in [7, 11, 19, 23, 31, 1009]:
        assert (p % 4 == 3)
        a = (p - 1) * (p - 1) % p  # 平方数
        if a == 0:
            continue
        x = pow(a, (p + 1) // 4, p)
        assert x * x % p == a

    print("All tests passed.")
